package com.chheang.mengheak.adapter.gateway.adapter; import com.chheang.mengheak.adapter.domain.*; import com.chheang.mengheak.adapter.external.aba.*; import org.junit.jupiter.api.*; import java.math.BigDecimal; import static org.assertj.core.api.Assertions.*; class AbaPaymentAdapterTest { @Test void mapsVendorResponse(){var r=new AbaPaymentAdapter(new AbaSdk()).pay(new PaymentCommand("a",new BigDecimal("10"),"USD","ORDER-1")); assertThat(r.provider()).isEqualTo(PaymentProvider.ABA); assertThat(r.status()).isEqualTo(PaymentStatus.SUCCESS);} }
